MODULE VORDIV_TO_UV_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to VORDIV_TO_UV
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPSPVOR_SHAPE(2)
  INTEGER(KIND=C_INT) :: IPSPDIV_SHAPE(2)
  INTEGER(KIND=C_INT) :: IPSPU_SHAPE(2)
  INTEGER(KIND=C_INT) :: IPSPV_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKVSETUV_SHAPE(1)
END TYPE ARGS_INFO

END MODULE VORDIV_TO_UV_ARGS_INFO_MOD

SUBROUTINE VORDIV_TO_UV(PSPVOR, PSPDIV, PSPU, PSPV, KSMAX, KVSETUV)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT
USE VORDIV_TO_UV_ARGS_INFO_MOD,  ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE VORDIV_TO_UV_CPP_BINDING_SP(ARGS, KSMAX, PSPVOR, PSPDIV, PSPU, PSPV, KVSETUV) &
  &  BIND(C, NAME="vordiv_to_uv_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT
  USE VORDIV_TO_UV_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KSMAX
  REAL(KIND=C_FLOAT),            INTENT(IN)  :: PSPVOR(*)
  REAL(KIND=C_FLOAT),            INTENT(IN)  :: PSPDIV(*)
  REAL(KIND=C_FLOAT),            INTENT(OUT) :: PSPU(*)
  REAL(KIND=C_FLOAT),            INTENT(OUT) :: PSPV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETUV(*)
END SUBROUTINE VORDIV_TO_UV_CPP_BINDING_SP
SUBROUTINE VORDIV_TO_UV_CPP_BINDING_DP(ARGS, KSMAX, PSPVOR, PSPDIV, PSPU, PSPV, KVSETUV) &
  &  BIND(C, NAME="vordiv_to_uv_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT
  USE VORDIV_TO_UV_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KSMAX
  REAL(KIND=C_DOUBLE),           INTENT(IN)  :: PSPVOR(*)
  REAL(KIND=C_DOUBLE),           INTENT(IN)  :: PSPDIV(*)
  REAL(KIND=C_DOUBLE),           INTENT(OUT) :: PSPU(*)
  REAL(KIND=C_DOUBLE),           INTENT(OUT) :: PSPV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSETUV(*)
END SUBROUTINE VORDIV_TO_UV_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),              INTENT(IN)  :: PSPVOR(:,:)
REAL(KIND=JPRB),              INTENT(IN)  :: PSPDIV(:,:)
REAL(KIND=JPRB),              INTENT(OUT) :: PSPU(:,:)
REAL(KIND=JPRB),              INTENT(OUT) :: PSPV(:,:)
INTEGER(KIND=JPIM),           INTENT(IN)  :: KSMAX
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSETUV(:)

TYPE(ARGS_INFO) :: ARGS

ARGS%IPSPVOR_SHAPE = SHAPE(PSPVOR, KIND=C_INT)
ARGS%IPSPDIV_SHAPE = SHAPE(PSPDIV, KIND=C_INT)
ARGS%IPSPU_SHAPE = SHAPE(PSPU, KIND=C_INT)
ARGS%IPSPV_SHAPE = SHAPE(PSPV, KIND=C_INT)
IF (PRESENT(KVSETUV)) THEN
  ARGS%IKVSETUV_SHAPE = SHAPE(KVSETUV, KIND=C_INT)
ELSE
  ARGS%IKVSETUV_SHAPE = 0_C_INT
ENDIF

#ifdef TRANS_SINGLE
CALL VORDIV_TO_UV_CPP_BINDING_SP(ARGS, KSMAX, PSPVOR, PSPDIV, PSPU, PSPV, KVSETUV=KVSETUV)
#else
CALL VORDIV_TO_UV_CPP_BINDING_DP(ARGS, KSMAX, PSPVOR, PSPDIV, PSPU, PSPV, KVSETUV=KVSETUV)
#endif

END SUBROUTINE VORDIV_TO_UV
